        load(passenger);require(call("IsUnitLoaded",{passenger}).bits && vm.global("loaded_count").bits==1 && vm.global("loaded_event_unit").bits==passenger.bits && vm.global("loaded_event_carrier").bits==carrier.bits && vm.global("loaded_trigger_unit").bits==passenger.bits,"Loaded native context and real manifest disagree");
        if(mode==L"grid-drop" || mode==L"goal-drop"){
            auto& w=*session.world();auto& data=w.data();auto& path=*data.pathing;auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};auto xy=[&](float x,float y){return WorldPoint{real(x),real(y)};};auto centre=w.pathCell(number(c->x),number(c->y));require(centre.has_value() && session.units().at(passenger.bits)->collision<=32,"Fixture cargo geometry differs");int cx=int(*centre%path.width),cy=int(*centre/path.width);auto cell=[&](int x,int y){return xy(data.terrain.origin[0]+x*32+16,data.terrain.origin[1]+y*32+16);};std::set<size_t> sampled;for(int ring=0;ring<=8;++ring){float radius=std::min(float(ring*32),250.f);for(int side=0;side<(ring?16:1);++side){float angle=side*6.28318530718f/16;auto p=w.clamp(xy(number(c->x)+std::cos(angle)*radius,number(c->y)+std::sin(angle)*radius));if(auto index=w.pathCell(number(p.x),number(p.y)))sampled.insert(*index);}}std::optional<WorldPoint> hole;for(int y=cy-10;y<=cy+10;++y)for(int x=cx-10;x<=cx+10;++x){auto p=cell(x,y);auto index=w.pathCell(number(p.x),number(p.y));if(!index)continue;float distance=std::hypot(number(p.x)-number(c->x),number(p.y)-number(c->y));if(!hole && distance>120 && distance<220 && !sampled.contains(*index) && std::hypot(number(p.x)-number(session.units().at(hero.bits)->x),number(p.y)-number(session.units().at(hero.bits)->y))>100 && std::hypot(number(p.x)-number(session.units().at(siege.bits)->x),number(p.y)-number(session.units().at(siege.bits)->y))>100)hole=p;w.terrainPathable(p,1,false);}require(hole.has_value(),"No unsampled ground cell in fixture");auto holeIndex=*w.pathCell(number(hole->x),number(hole->y));int hx=int(holeIndex%path.width),hy=int(holeIndex/path.width);for(auto [dx,dy]:std::array<std::pair<int,int>,5>{{{0,0},{1,0},{-1,0},{0,1},{0,-1}}})w.terrainPathable(cell(hx+dx,hy+dy),1,true);require(w.pathPointFree(*hole,session.units().at(passenger.bits)->collision,PathMovement::Ground),"Fixture landing cell is blocked");if(mode==L"goal-drop"){for(auto [dx,dy]:std::array<std::pair<int,int>,5>{{{0,0},{1,0},{-1,0},{0,1},{0,-1}}})w.terrainPathable(cell(cx+dx,cy+dy),1,true);require(w.pathRegionsNear(*hole,cell(cx,cy),session.units().at(passenger.bits)->collision,PathMovement::Ground,0)==false,"Fixture shores unexpectedly connected");c->cargoDrop=CargoDropOrder{{c->x,c->y},session.simulationTime(),852048,*hole};c->currentOrder=852048;session.advance(1./32);require(!call("IsUnitLoaded",{passenger}).bits,"Targeted unload did not release passenger");auto unit=session.units().at(passenger.bits);require(w.pathRegionsNear({unit->x,unit->y},*hole,unit->collision,PathMovement::Ground,0)==true,"Passenger landed on the wrong shore");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS target_shore_cargo_landing\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}auto blocker=call("CreateUnit",{call("Player",{vm.integer(0)}),vm.integer(int(ObjectData::code("hfoo"))),point(int(number(hole->x))),point(int(number(hole->y))),point(0)});require(!call("IssueTargetOrder",{carrier,vm.string("unload"),passenger}).bits && call("IsUnitLoaded",{passenger}).bits,"Unload ignored the occupied landing cell");call("SetUnitPosition",{blocker,point(1024),point(1024)});require(call("IssueTargetOrder",{carrier,vm.string("unload"),passenger}).bits && !call("IsUnitLoaded",{passenger}).bits,"Unload missed the only passable ground cell");auto unit=session.units().at(passenger.bits);require(w.pathCell(number(unit->x),number(unit->y))==w.pathCell(number(hole->x),number(hole->y)),"Passenger landed outside the available cell");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS narrow_grid_cargo_landing\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
        }
