        if(mode==L"crash-remove"){
            auto first=session.units().at(passenger.bits),second=session.units().at(hero.bits);first->sourceSummoned=true;load(hero);call("KillUnit",{carrier});auto dizzy=ObjectData::code("Bchd");require(!session.units().contains(carrier.bits) && vm.global("crash_damage_events").bits==1,"Crash damage callback did not remove carrier");require(!first->transport && !second->transport && !first->buffs.contains(dizzy) && !second->buffs.contains(dizzy),"Removed carrier left cargo or applied stale crash status");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS crash_removed_carrier_releases_remaining_cargo\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
        }
        if(mode==L"crash-revive"){
            auto first=session.units().at(passenger.bits),second=session.units().at(hero.bits);first->sourceSummoned=true;load(hero);call("KillUnit",{carrier});require(number(c->life)>0 && vm.global("crash_damage_events").bits==1,"Crash damage callback did not revive carrier");require(!first->transport && second->transport==carrier.bits && c->cargo.size()==1 && c->cargo.front()==hero.bits && session.cargoUsed(carrier.bits)==1,"Revived carrier lost an unprocessed passenger");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS crash_revived_carrier_preserves_remaining_cargo\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
        }
